effect.script:
function animate(env,el,p) {
let groups = [];
groups.push(0);
el.shaderGroups = groups;
return el;
}

effect.shader:
vec4 newLayer( vec4 a, vec4 b) {
return a * (1. - b.a) + b;
}
mat2 rot2m(float a){
float s = sin(a);
float c = cos(a);
return mat2(c, -s, s, c);
}
vec2 l2s( vec2 v ) {
return (vec4(v,0.,1.)*acLayerToScreen).xy;
}
#define fragCoord gl_FragCoord.xy
float sun(vec2 uv, float battery)
{
float val = smoothstep(0.3, 0.29, length(uv));
float bloom = smoothstep(0.7, 0.0, length(uv));
float cut = 3.0 * sin((uv.y + progressa * 0.2 * (battery + 0.02)) * 100.0)
+ clamp(uv.y * 14.0 + 1.0, -6.0, 6.0);
cut = clamp(cut, 0.0, 1.0);
return clamp(val * cut, 0.0, 1.0) + bloom * 0.6;
}
float grid(vec2 uv, float battery)
{
vec2 size = vec2(uv.y, uv.y * uv.y * 0.2) * 0.01;
uv += vec2(0.0, progressb * 4.0 * (battery + 0.05));
uv = abs(fract(uv) - 0.5);
vec2 lines = smoothstep(size, vec2(0.0), uv);
lines += smoothstep(size * 5.0, vec2(0.0), uv) * 0.4 * battery;
return clamp(lines.x + lines.y, 0.0, 3.0);
}
void main() {
if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
vec2 sscaleVec;
sscaleVec = vec2(1.0*sstretch.x,1.0*sstretch.y);
vec4 texColor = texture2DCv(inputImg.texture, (acScreenNorm/sscaleVec));
vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;
vec2 syamjaidtz;
syamjaidtz = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
syamjaidtz.y*=acLayerSize.y/acLayerSize.x;
if (visible) { syamjaidtz /= 100.0; }
else { syamjaidtz /= scalex? (scale+3.5) : scale; }
syamjaidtz *= rot2m((180.0+angle)*0.0174533);
syamjaidtz += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
vec2 sunst;
sunst = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
sunst.y*=acLayerSize.y/acLayerSize.x;
sunst /= scalex? (scalen+3.5) : scalen;
sunst *= rot2m((180.0+anglen)*0.0174533);
sunst += vec2((375.0+positionn.x), (-180.0+positionn.y))*vec2(-1.,1.)/500.;
vec4 fragColor;
vec2 scaleVec;
scaleVec = vec2(1.0*stretch.x,1.0*stretch.y);
vec2 uv = syamjaidtz/scaleVec;
float battery = 1.0;
{
float fog = smoothstep(0.1, -0.02, abs(uv.y + 0.2));
vec3 col = vec3(0.0, 0.1, 0.2);
if (uv.y < -0.2)
{
uv.y = 3.0 / (abs(uv.y + 0.2) + 0.05);
uv.x *= uv.y * 1.0;
float gridVal = grid(uv, battery);
col = mix(col, vec3(color4.rgb), gridVal);
}
else
{
vec2 sunUV = sunst;
sunUV += vec2(0.75, 0.2);
col = vec3(color1.rgb);
float sunVal = sun(sunUV, battery);
col = mix(col, vec3(vec3(color3.rgb)), sunUV.y * 2.0 + 0.2);
col = mix(vec3(0.0, 0.0, 0.0), col, (sunVal*alphan));
col += mix( col, mix(vec3(color4.rgb), vec3(0.0, 0.0, 0.2), clamp(uv.y * 3.5 + 3.0, 0.0, 1.0)), vec3(1.0, 1.0, 1.0) );
col = mix(col, vec3(0.0, 0.0, 0.2), 1.0 - smoothstep(0.075 - 0.0001, 0.075, vec3(1.0, 1.0, 1.0)));
}
col += fog * fog * fog;
col = mix(vec3(color2.rgb), col, battery * 0.7);
fragColor = vec4(col,1.0);
}
vec4 factor = mix(texColorX,fragColor,1.0);
vec4 resultfinal;
if( blendMode==0 ) {
resultfinal = (factor * bright) * texColor.a;
} else if( blendMode==1 ) {
factor *= bright;
vec4 c = factor + vec4(1.)*(1.-factor.a);
resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
} else if( blendMode==2 ) {
factor *= bright;
resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
}
gl_FragColor = mix(texColor, resultfinal, alpha);
}
}
